with scored as (select id, location, lead(budget, 2) over (partition by dept_name order by budget, id) as next_budget, avg(budget) over (partition by dept_name order by budget, id rows between 5 preceding and current row) as budget_avg_5 from departments where location in ('New York', 'Chiang Mai', 'London')) select id, location, budget_avg_5, case when location rlike '^(Chiang Mai|London)$' then 'CORE' else 'OTHER_ZONE' end as location_zone from scored order by id desc
